CREATE OR REPLACE FUNCTION private.offer_claim_for_review(p_offer_id uuid) RETURNS public.teklifler LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ declare r public.teklifler; u uuid:=auth.uid(); begin if u is null then raise exception 'Oturum gerekli'; end if; if not (public.staff_has_perm('offers.evaluate') or private.is_admin()) then raise exception 'Teklif değerlendirme yetkisi gerekli'; end if; select * into r from public.teklifler where id=p_offer_id for update; if not found then raise exception 'Teklif bulunamadı'; end if; if r.evaluation_status='evaluating' and r.evaluated_by is distinct from u then raise exception 'Teklif başka bir personel tarafından değerlendiriliyor'; end if; update public.teklifler set evaluation_status='evaluating',evaluated_by=u,evaluated_at=now(),updated_at=now() where id=p_offer_id returning * into r; insert into public.activity_logs(actor_id,action,entity_type,entity_id,metadata) values(u,'offer_claimed','teklifler',p_offer_id,jsonb_build_object('status','evaluating')); return r; end $$;
CREATE OR REPLACE FUNCTION private.offer_evaluate(p_offer_id uuid,p_status text,p_note text DEFAULT NULL::text) RETURNS public.teklifler LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ declare r public.teklifler; u uuid:=auth.uid(); v text:=lower(trim(coalesce(p_status,''))); begin if u is null then raise exception 'Oturum gerekli'; end if; if not (public.staff_has_perm('offers.evaluate') or private.is_admin()) then raise exception 'Teklif değerlendirme yetkisi gerekli'; end if; if v not in ('accepted','rejected','reviewing') then raise exception 'Geçersiz değerlendirme durumu'; end if; select * into r from public.teklifler where id=p_offer_id for update; if not found then raise exception 'Teklif bulunamadı'; end if; if r.evaluation_status='evaluating' and r.evaluated_by is distinct from u and not private.is_admin() then raise exception 'Teklif kilitli'; end if; update public.teklifler set status=case when v='accepted' then 'accepted' when v='rejected' then 'rejected' else status end,evaluation_status=case when v='reviewing' then 'evaluating' else v end,evaluated_by=u,evaluated_at=now(),rejected_at=case when v='rejected' then now() else rejected_at end,accepted_at=case when v='accepted' then now() else accepted_at end,updated_at=now() where id=p_offer_id returning * into r; if p_note is not null and length(trim(p_note))>0 then insert into public.activity_logs(actor_id,action,entity_type,entity_id,metadata) values(u,'offer_evaluation_note','teklifler',p_offer_id,jsonb_build_object('note',left(p_note,4000))); end if; insert into public.activity_logs(actor_id,action,entity_type,entity_id,metadata) values(u,'offer_evaluated','teklifler',p_offer_id,jsonb_build_object('status',v,'note',left(coalesce(p_note,''),4000))); if v in ('accepted','rejected') then insert into public.notifications(recipient_user_id,kind,title,body,offer_id) select s.user_id,'offer_evaluation','Teklif güncellendi',case when v='accepted' then 'Teklif kabul edildi.' else 'Teklif reddedildi.' end,p_offer_id from public.staff s where s.active=true and s.user_id<>u; end if; return r; end $$;
CREATE OR REPLACE FUNCTION private.offer_update_event_date(p_offer_id uuid,p_event_date date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE old_date date; delta interval; u uuid := auth.uid(); r public.teklifler; j public.jobs; job_count integer := 0; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'Oturum gerekli'; END IF; IF NOT (public.staff_has_perm('schedule.manage') OR public.staff_has_perm('offers.update') OR private.is_admin()) THEN RAISE EXCEPTION 'Etkinlik tarihi düzenleme yetkisi gerekli'; END IF; IF p_event_date IS NULL THEN RAISE EXCEPTION 'Etkinlik tarihi gerekli'; END IF; SELECT * INTO r FROM public.teklifler WHERE id=p_offer_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Teklif bulunamadı'; END IF; old_date:=r.event_date; IF old_date IS NULL THEN delta:=interval '0'; ELSE delta:=make_interval(days=>(p_event_date-old_date)); END IF; PERFORM set_config('stagepulse.skip_event_sync','on',true); UPDATE public.teklifler SET event_date=p_event_date,updated_at=now() WHERE id=p_offer_id RETURNING * INTO r; PERFORM set_config('stagepulse.skip_event_sync','off',true); UPDATE public.settlements SET event_date=p_event_date,updated_at=now() WHERE offer_id=p_offer_id; FOR j IN SELECT * FROM public.jobs WHERE offer_id=p_offer_id FOR UPDATE LOOP UPDATE public.jobs SET setup_at=CASE WHEN j.setup_at IS NULL THEN NULL ELSE j.setup_at+delta END,event_at=CASE WHEN j.event_at IS NULL THEN NULL ELSE j.event_at+delta END,teardown_at=CASE WHEN j.teardown_at IS NULL THEN NULL ELSE j.teardown_at+delta END,setup_start_at=CASE WHEN j.setup_start_at IS NULL THEN NULL ELSE j.setup_start_at+delta END,event_start_at=CASE WHEN j.event_start_at IS NULL THEN NULL ELSE j.event_start_at+delta END,event_end_at=CASE WHEN j.event_end_at IS NULL THEN NULL ELSE j.event_end_at+delta END,teardown_end_at=CASE WHEN j.teardown_end_at IS NULL THEN NULL ELSE j.teardown_end_at+delta END WHERE id=j.id; job_count:=job_count+1; INSERT INTO public.notifications(recipient_user_id,kind,title,body,offer_id) SELECT s.user_id,'event_change','Etkinlik tarihi değişti','Etkinlik tarihi güncellendi.',p_offer_id FROM public.job_staff js JOIN public.staff s ON s.id=js.staff_id WHERE js.job_id=j.id AND s.active=true AND s.user_id IS NOT NULL; END LOOP; INSERT INTO public.activity_logs(actor_id,action,entity_type,entity_id,metadata) VALUES(u,'event_date_changed','teklifler',p_offer_id,jsonb_build_object('old_date',old_date,'new_date',p_event_date,'jobs_updated',job_count)); RETURN jsonb_build_object('offer_id',p_offer_id,'old_date',old_date,'new_date',p_event_date,'jobs_updated',job_count); END; $$;
REVOKE ALL ON FUNCTION private.offer_claim_for_review(uuid) FROM PUBLIC; REVOKE ALL ON FUNCTION private.offer_evaluate(uuid,text,text) FROM PUBLIC; REVOKE ALL ON FUNCTION private.offer_update_event_date(uuid,date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION private.offer_claim_for_review(uuid) TO authenticated; GRANT EXECUTE ON FUNCTION private.offer_evaluate(uuid,text,text) TO authenticated; GRANT EXECUTE ON FUNCTION private.offer_update_event_date(uuid,date) TO authenticated;
CREATE OR REPLACE FUNCTION public.offer_claim_for_review(p_offer_id uuid) RETURNS public.teklifler LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT private.offer_claim_for_review(p_offer_id) $$;
CREATE OR REPLACE FUNCTION public.offer_evaluate(p_offer_id uuid,p_status text,p_note text DEFAULT NULL::text) RETURNS public.teklifler LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT private.offer_evaluate(p_offer_id,p_status,p_note) $$;
CREATE OR REPLACE FUNCTION public.offer_update_event_date(p_offer_id uuid,p_event_date date) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT private.offer_update_event_date(p_offer_id,p_event_date) $$;
REVOKE ALL ON FUNCTION public.offer_claim_for_review(uuid) FROM PUBLIC; REVOKE ALL ON FUNCTION public.offer_evaluate(uuid,text,text) FROM PUBLIC; REVOKE ALL ON FUNCTION public.offer_update_event_date(uuid,date) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.offer_claim_for_review(uuid) FROM anon; REVOKE EXECUTE ON FUNCTION public.offer_evaluate(uuid,text,text) FROM anon; REVOKE EXECUTE ON FUNCTION public.offer_update_event_date(uuid,date) FROM anon;
GRANT EXECUTE ON FUNCTION public.offer_claim_for_review(uuid) TO authenticated; GRANT EXECUTE ON FUNCTION public.offer_evaluate(uuid,text,text) TO authenticated; GRANT EXECUTE ON FUNCTION public.offer_update_event_date(uuid,date) TO authenticated;
